public struct WeeklyTimetable {
    public var semester: String
    public var gridTitle: String
    public var days: [String]
    public var rows: [TimetableRow]
    public var legend: [DepartmentColorOption]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(semester: String, gridTitle: String, days: [String], rows: [TimetableRow], legend: [DepartmentColorOption]) {
        self.semester = semester
        self.gridTitle = gridTitle
        self.days = days
        self.rows = rows
        self.legend = legend
    }
}



extension WeeklyTimetable: Equatable, Hashable {
    public static func ==(lhs: WeeklyTimetable, rhs: WeeklyTimetable) -> Bool {
        if lhs.semester != rhs.semester {
            return false
        }
        if lhs.gridTitle != rhs.gridTitle {
            return false
        }
        if lhs.days != rhs.days {
            return false
        }
        if lhs.rows != rhs.rows {
            return false
        }
        if lhs.legend != rhs.legend {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(semester)
        hasher.combine(gridTitle)
        hasher.combine(days)
        hasher.combine(rows)
        hasher.combine(legend)
    }
}


