#endif
public struct FfiConverterTypeWeeklyTimetable: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WeeklyTimetable {
        return
            try WeeklyTimetable(
                semester: FfiConverterString.read(from: &buf), 
                gridTitle: FfiConverterString.read(from: &buf), 
                days: FfiConverterSequenceString.read(from: &buf), 
                rows: FfiConverterSequenceTypeTimetableRow.read(from: &buf), 
                legend: FfiConverterSequenceTypeDepartmentColorOption.read(from: &buf)
        )
    }

    public static func write(_ value: WeeklyTimetable, into buf: inout [UInt8]) {
        FfiConverterString.write(value.semester, into: &buf)
        FfiConverterString.write(value.gridTitle, into: &buf)
        FfiConverterSequenceString.write(value.days, into: &buf)
        FfiConverterSequenceTypeTimetableRow.write(value.rows, into: &buf)
        FfiConverterSequenceTypeDepartmentColorOption.write(value.legend, into: &buf)
    }
}


